// 1) 애플리케이션 전체에서 딱 하나. 시작할 때 만들고 끝날 때 닫는다.
EntityManagerFactory emf = Persistence.createEntityManagerFactory("hello");

// 2) 요청(또는 작업) 하나마다 새로 만든다.
EntityManager em = emf.createEntityManager();

// 3) JPA 의 모든 데이터 변경은 트랜잭션 안에서 일어난다.
EntityTransaction tx = em.getTransaction();
tx.begin();

try {
    // ... 여기서 작업 ...
    tx.commit();
} catch (Exception e) {
    tx.rollback();
} finally {
    em.close();      // 반드시 닫는다
}

emf.close();

Member member = new Member();
member.setId(1L);
member.setName("김관현");

// 여기까지. EntityManager 근처에도 안 갔다.

EntityManager em = emf.createEntityManager();
em.getTransaction().begin();

Member member = new Member();
member.setId(1L);
member.setName("김관현");

em.persist(member);   // ← 이 순간 영속 상태가 된다

Member member = em.find(Member.class, 1L);
// DB 에서 읽어 온 뒤 1차 캐시에 넣는다. 이제 영속 상태.

member.setName("김관현2");
// 저장 코드가 없다. 그런데 커밋하면 UPDATE 가 나간다. (4.2절 변경 감지)

Member member = em.find(Member.class, 1L);   // 영속

em.detach(member);        // 이 엔티티 하나만 관리에서 뺀다
// em.clear();            // 컨텍스트를 통째로 비운다
// em.close();            // 컨텍스트를 닫는다

member.setName("바뀐이름");
em.getTransaction().commit();

// UPDATE 가 나가지 않는다. 아무 일도 안 일어난다.

Member member = em.find(Member.class, 1L);
em.remove(member);

// 이 시점에 DELETE 는 아직 안 나갔다.
// 1차 캐시에서 빠지고, 쓰기 지연 저장소에 DELETE 가 쌓인다.

tx.begin();

System.out.println("===== persist 호출 직전 =====");

Member member = new Member();
member.setId(100L);
member.setName("김관현");
em.persist(member);

System.out.println("===== persist 호출 직후 =====");

tx.commit();

System.out.println("===== commit 직후 =====");
